'cases': [{'input': [{'parameter': 'index', 'value': '2'}, {'parameter': 'price', 'value': 'Num.valueOf(200)'}, {'parameter': 'amount', 'value': 'Num.valueOf(5)'}], 'expected': 'sameReferenceOnMultipleCalls', 'description': 'After creating the entry trade, invoke getEntry() three times in a row. All returned objects must be the same reference (==), proving that getEntry() is idempotent and does not create new objects.'}]}, {'group': 'Position.getEntry after serialization', 'cases': [{'input': [{'parameter': 'index', 'value': '1'}, {'parameter': 'price', 'value': 'Num.valueOf(75)'}, {'parameter': 'amount', 'value': 'Num.valueOf(15)'}], 'expected': 'equalTradeAfterDeserialization', 'description': 'Create a Position with an entry trade, serialize the Position to a byte array, deserialize it back, and then call getEntry(). The deserialized Trade must be equal (by .equals) to the original entry Trade, confirming that the entry field is correctly persisted.'}]}]
